t.script:


document.addEventListener("DOMContentLoaded", function () {

    var commentElements =
        document.querySelectorAll(".js-comment-content");

    commentElements.forEach(function (element) {

        var text = element.textContent || "";

        var urlRegex = /(https?:\/\/[^\s]+)/g;

        var parts = text.split(urlRegex);

        element.innerHTML = "";

        parts.forEach(function (part) {

            if (/^https?:\/\//i.test(part)) {

                var cleanUrl = part;
                var trailing = "";

                while (
                    cleanUrl.length > 0 &&
                    /[.,!?;:)\]}]$/.test(cleanUrl)
                ) {

                    trailing =
                        cleanUrl.slice(-1) + trailing;

                    cleanUrl =
                        cleanUrl.slice(0, -1);

                }

                var link =
                    document.createElement("a");

                link.href = cleanUrl;

                link.textContent = cleanUrl;

                link.target = "_blank";

                link.rel =
                    "noopener noreferrer";

                link.className =
                    "comment-product-link";

                element.appendChild(link);

                if (trailing) {

                    element.appendChild(
                        document.createTextNode(trailing)
                    );

                }

            } else {

                element.appendChild(
                    document.createTextNode(part)
                );

            }

        });

    });

});
